let norm = {};
try { norm = $('Normalize WhatsApp Input').first().json || {}; } catch (e) { norm = $json || {}; }
const ctx = $json || {};
const to   = String(norm.phone || "").trim();
const id   = String(norm.interactive_id || "").trim();
const text = String(norm.normalized_text || norm.message_text || "").trim();
const greeting = norm.is_greeting_only === true;

// ---- language detection (mirror the customer, default Arabic) ----
const isEmailStr = (s) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(s || "").trim());
function detectLang(s) {
  s = String(s || "");
  if (/[؀-ۿ]/.test(s)) return "ar";                 // any Arabic letter
  if (/[A-Za-z]/.test(s) && !isEmailStr(s)) return "en";       // latin word (not an email)
  return "";
}
const clientName = String(norm.client_name || ctx.property_name || ctx.name || "").trim();
let lang = detectLang(norm.message_text || text) ||
           String(ctx.lang || ctx.property_language || "").toLowerCase() ||
           detectLang(clientName) || "ar";
if (lang !== "en") lang = "ar";
const L = (ar, en) => (lang === "en" ? en : ar);

// language-aware base + link builders
const BASE = lang === "en" ? "https://businesspartner.sa" : "https://businesspartner.sa/ar";

const cut = (s, n) => { s = String(s || ""); return s.length > n ? s.slice(0, n - 1) + "…" : s; };
const catBySlug = (slug) => CATS.find(c => c[0] === slug);
const catName = (c) => L(c[1], c[2]);
const svcName = (s) => L(s[1], s[2]);

function listMsg(header, bodyText, footer, button, sections) {
  const safeSections = (sections || []).map(sec => ({
    title: cut(sec.title, 24),
    rows: (sec.rows || []).map(r => ({
      id: cut(r.id, 200),
      title: cut(r.title, 24),
      description: cut(r.description, 72)
    }))
  }));
  return JSON.stringify({
    messaging_product: "whatsapp", recipient_type: "individual", to,
    type: "interactive",
    interactive: { type: "list",
      header: { type: "text", text: cut(header, 60) },
      body:   { text: cut(bodyText, 1024) },
      footer: { text: cut(footer, 60) },
      action: { button: cut(button, 20), sections: safeSections } }
  });
}
function textMsg(t) {
  return JSON.stringify({ messaging_product: "whatsapp", recipient_type: "individual", to,
    type: "text", text: { preview_url: true, body: cut(t, 4000) } });
}

