function subMenu(slug, page) {
  const c = catBySlug(slug); if (!c) return null;
  // WhatsApp caps an interactive list at 10 rows, and a category can hold 37
  // services. Page through them instead of silently cutting the list at 8 —
  // the old behaviour made 84 of the 140 services unreachable on WhatsApp.
  const all = SVCS[slug] || [];
  const PER = 6;  // 6 services + next + prev + «all» + «main» = the 10-row cap
  const p = Math.max(0, Math.min(Math.floor(Number(page) || 0), Math.ceil(all.length / PER) - 1));
  const svc = all.slice(p * PER, p * PER + PER);
  const more = (p + 1) * PER < all.length;
  const shortT = (nm) => cut(String(nm).split(/[(—\-–—]/)[0].trim(), 24);
  const rows = svc.map(s => ({ id: "svc_" + s[0], title: shortT(svcName(s)), description: cut(svcName(s), 72) }));
  if (slug === "recruitment" && p === 0) rows.unshift({
    id: "jobseeker",
    title: L("🧑‍🎓 باحث عن عمل؟ قدّم", "🧑‍🎓 Job seeker? Apply"),
    description: L("تصفّح الوظائف المعلنة وقدّم عليها (للأفراد)", "Browse open jobs and apply (for individuals)")
  });
  if (more) rows.push({
    id: "catp_" + slug + "_" + (p + 1),
    title: L("⬇️ خدمات أخرى في القسم", "⬇️ More in this category"),
    description: L("عرض بقية خدمات «" + catName(c) + "»", "Show the rest of \"" + catName(c) + "\"")
  });
  if (p > 0) rows.push({
    id: "catp_" + slug + "_" + (p - 1),
    title: L("⬆️ الصفحة السابقة", "⬆️ Previous page"),
    description: L("ارجع لخدمات القسم السابقة", "Back to the previous services")
  });
  rows.push({ id: "catall_" + slug, title: L("📋 كل خدمات القسم", "📋 All category services"), description: L("افتح صفحة القسم كاملة على الموقع", "Open the full category page on the site") });
  rows.push({ id: "back_main", title: L("🔙 القائمة الرئيسية", "🔙 Main menu"), description: L("ارجع لكل الأقسام", "Back to all sections") });
  const pageNote = all.length > PER
    ? L("  (" + (p * PER + 1) + "–" + Math.min((p + 1) * PER, all.length) + " من " + all.length + ")",
        "  (" + (p * PER + 1) + "–" + Math.min((p + 1) * PER, all.length) + " of " + all.length + ")")
    : "";
  return listMsg(c[3] + " " + catName(c),
    L("اختر الخدمة اللي تبيها من «" + catName(c) + "»" + pageNote + " 👇\nوإذا ما لقيت اللي تبي، اكتب لي سؤالك والوكيل يساعدك.",
      "Choose the service you need from \"" + catName(c) + "\"" + pageNote + " 👇\nIf you don't find it, just type your question and the agent will help."),
    L("بيزنس بارتنر", "Business Partner"), L("اختر الخدمة", "Choose service"), [{ title: catName(c), rows }]);
}

