function svcReply(code) {
  let found = null, foundSlug = null;
  for (const slug in SVCS) { const m = (SVCS[slug] || []).find(s => s[0] === code); if (m) { found = m; foundSlug = slug; break; } }
  if (!found) return null;
  const link = BASE + "/services/" + found[3];
  return textMsg(L(
    "✨ *" + svcName(found) + "*\n\nنخدمك فيها من الألف للياء — نجهّز مستنداتك، نرفعها على الجهة المختصة، ونتابع حتى الإصدار، بأتعاب واضحة. 📌\n\n🔗 كل التفاصيل هنا:\n" + link + "\n\nتبي نبدأ طلبك أو عندك سؤال؟ اكتب لي 👇 أو احجز استشارة مجانية 🗓️\n\n" + CONTACT_FOOTER,
    "✨ *" + svcName(found) + "*\n\nWe handle it end to end — prepare your documents, submit to the relevant authority, and follow up until issuance, with clear fees. 📌\n\n🔗 Full details here:\n" + link + "\n\nWant to start your request or have a question? Message me 👇 or book a free consultation 🗓️\n\n" + CONTACT_FOOTER
  ));
}

